'use strict';
const assert = require('node:assert/strict');
const { CommercialReference } = require('./commercial-reference-harness.cjs');
const [base, token, job, customer] = process.argv.slice(2);
(async () => {
  let online = true, lose = false, calls = 0;
  const request = async (method, path, body) => {
    assert(online, 'staging must not contact the server'); calls++;
    const response = await fetch(base + path, { method, headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' }, ...(body ? { body: JSON.stringify(body) } : {}) });
    const result = { status: response.status, body: await response.json() };
    if (lose && method === 'POST') { lose = false; throw new Error('lost response after commit'); }
    return result;
  };
  const client = new CommercialReference(request);
  const created = client.stageCreate('estimate', Number(job), { customer_id: Number(customer), title: 'Reference conversion source', line_items: [] });
  await client.submit(created); assert.equal(created.state, 'accepted');
  const path = `/estimates/${created.receipt.id}`;
  let source = (await request('GET', path)).body.data;
  online = false; const before = calls;
  const stale = client.stageConversion('estimate', source);
  assert.equal(calls, before); online = true;
  const edit = client.stageEdit('estimate', source, { title: 'Current reference conversion' });
  await client.submit(edit); await client.submit(stale);
  assert.equal(stale.state, 'needs_review'); assert.equal(stale.receipt.outcome, 'stale_commercial_revision');
  await assert.rejects(() => client.submit(stale), /explicitly review/);
  source = (await request('GET', path)).body.data;
  const convert = client.reviewedConversion(stale, source);
  assert.notEqual(convert.intent.operation_id, stale.intent.operation_id);
  lose = true; await client.submit(convert); assert.equal(convert.state, 'unknown');
  await client.inspect(convert); assert.equal(convert.state, 'accepted');
  const first = convert.receipt;
  const invoicePath = `/invoices/${first.id}`;
  const invoice = (await request('GET', invoicePath)).body.data;
  online = false; const revert = client.stageConversion('invoice', invoice); online = true;
  assert.equal(revert.intent.cycle_id, first.cycle_id);
  lose = true; await client.submit(revert); assert.equal(revert.state, 'unknown');
  await client.inspect(revert); assert.equal(revert.state, 'accepted');
  source = (await request('GET', path)).body.data;
  const reconvert = client.stageConversion('estimate', source); await client.submit(reconvert);
  assert.equal(reconvert.state, 'accepted');
  assert.notEqual(first.id, reconvert.receipt.id); assert.notEqual(first.number, reconvert.receipt.number); assert.notEqual(first.cycle_id, reconvert.receipt.cycle_id);
  const next = (await request('GET', `/invoices/${reconvert.receipt.id}`)).body.data;
  const wrong = client.stageConversion('invoice', { ...next, cycle_id: first.cycle_id });
  await client.submit(wrong); assert.equal(wrong.state, 'needs_review'); assert.equal(wrong.receipt.outcome, 'stale_conversion_cycle');
  assert.throws(() => client.reviewedConversion(wrong, next), /exact cycle/);
  const replay = await request('POST', invoicePath + '/revert-to-estimate', revert.intent);
  assert.equal(replay.status, 200); assert.deepEqual(replay.body.data, revert.receipt);
  assert.equal((await request('GET', `/invoices/${next.id}`)).status, 200);
  console.log(JSON.stringify({ first, restored: revert.receipt, next: reconvert.receipt, stale: stale.receipt, wrongCycle: wrong.receipt }));
})().catch(error => { console.error(error); process.exitCode = 1; });
